INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Softwarearchitektur > Anwendungslösungen unter Berücksichtigung der bestehenden Systemarchitektur entwerfen sowie realisieren
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen Anwendungslösungen immer vollständig unabhängig von der bestehenden Systemarchitektur entworfen werden?', 2, '[{"text": "Nein", "correct": true, "because": "Integration in bestehende Systeme ist oft erforderlich"}, {"text": "Ja", "correct": false, "because": "Abhängigkeit ist üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Entwerfen von Anwendungslösungen die bestehende Systemarchitektur verändern?', 2, '[{"text": "Ja", "correct": true, "because": "Anpassungen können notwendig sein"}, {"text": "Nein", "correct": false, "because": "Veränderungen sind möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es möglich, Anwendungslösungen zu entwerfen, ohne die technischen Einschränkungen der bestehenden Architektur zu kennen?', 2, '[{"text": "Nein", "correct": true, "because": "Kenntnis der Einschränkungen ist essenziell für Realisierbarkeit"}, {"text": "Ja", "correct": false, "because": "Unwissenheit führt zu Fehlern"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Anwendungslösungen unter Berücksichtigung der bestehenden Systemarchitektur zwingend neue Technologien einführen?', 2, '[{"text": "Nein", "correct": true, "because": "Bestehende Technologien können ausreichen"}, {"text": "Ja", "correct": false, "because": "Nicht immer notwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Anwendungslösungen die Leistung der bestehenden Systemarchitektur negativ beeinflussen?', 2, '[{"text": "Ja", "correct": true, "because": "Schlecht integrierte Lösungen können Performance mindern"}, {"text": "Nein", "correct": false, "because": "Negative Effekte sind möglich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist beim Entwerfen von Anwendungslösungen unter Berücksichtigung der bestehenden Systemarchitektur am wichtigsten?', 2, '[{"text": "Kompatibilität", "correct": true, "because": "Sichert Integration und Funktion"}, {"text": "Kosten", "correct": false, "because": "Wichtig, aber sekundär"}, {"text": "Entwicklungsgeschwindigkeit", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft am besten, die bestehende Systemarchitektur beim Entwerfen von Anwendungslösungen zu berücksichtigen?', 3, '[{"text": "Architekturdokumentation analysieren", "correct": true, "because": "Liefert genaue Basisdaten"}, {"text": "Ad-hoc-Programmierung", "correct": false, "because": "Riskant und unstrukturiert"}, {"text": "Kundenbefragung", "correct": false, "because": "Wenig technischer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Risiko entsteht, wenn die bestehende Systemarchitektur beim Entwerfen ignoriert wird?', 2, '[{"text": "Inkompatibilität", "correct": true, "because": "Lösungen funktionieren nicht"}, {"text": "Geringere Benutzerfreundlichkeit", "correct": false, "because": "Indirekte Folge"}, {"text": "Höhere Wartungskosten", "correct": false, "because": "Spätere Auswirkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip sollte beim Entwerfen von Anwendungslösungen Priorität haben?', 2, '[{"text": "Modularität", "correct": true, "because": "Fördert Flexibilität und Integration"}, {"text": "Maximale Performance", "correct": false, "because": "Wichtig, aber nicht allein"}, {"text": "Minimale Codezeilen", "correct": false, "because": "Nicht entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die bestehende Systemarchitektur beim Realisieren von Anwendungslösungen?', 2, '[{"text": "Definiert technische Grenzen", "correct": true, "because": "Legt Machbarkeit fest"}, {"text": "Bestimmt Benutzeroberfläche", "correct": false, "because": "Nur indirekt"}, {"text": "Regelt Projektkosten", "correct": false, "because": "Nicht primäre Funktion"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte müssen beim Entwerfen von Anwendungslösungen unter Berücksichtigung der bestehenden Systemarchitektur beachtet werden?', 4, '[{"text": "Technische Kompatibilität", "correct": true, "because": "Sichert Integration"}, {"text": "Skalierbarkeit", "correct": true, "because": "Ermöglicht Wachstum"}, {"text": "Sicherheitsanforderungen", "correct": true, "because": "Schützt System"}, {"text": "Farbschema der UI", "correct": false, "because": "Nicht architekturrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools unterstützen das Entwerfen von Anwendungslösungen in bestehenden Architekturen?', 3, '[{"text": "UML-Diagramme", "correct": true, "because": "Visualisieren Strukturen"}, {"text": "Architektur-Frameworks", "correct": true, "because": "Strukturieren Entwurf"}, {"text": "Versionsverwaltung", "correct": true, "because": "Verfolgt Änderungen"}, {"text": "Texteditor", "correct": false, "because": "Zu allgemein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen treten beim Entwerfen von Anwendungslösungen in bestehenden Architekturen auf?', 4, '[{"text": "Legacy-Systeme", "correct": true, "because": "Erschweren Anpassung"}, {"text": "Technische Schulden", "correct": true, "because": "Verlangsamen Entwicklung"}, {"text": "Inkompatible Schnittstellen", "correct": true, "because": "Stören Integration"}, {"text": "Mangelnde Kreativität", "correct": false, "because": "Kein technisches Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien sollten beim Entwerfen von Anwendungslösungen beachtet werden?', 3, '[{"text": "Wiederverwendbarkeit", "correct": true, "because": "Fördert Effizienz"}, {"text": "Lose Kopplung", "correct": true, "because": "Erleichtert Änderungen"}, {"text": "Konsistenz", "correct": true, "because": "Sichert Harmonie"}, {"text": "Maximale Komplexität", "correct": false, "because": "Kontraproduktiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind beim Realisieren von Anwendungslösungen essenziell?', 3, '[{"text": "Analyse der bestehenden Architektur", "correct": true, "because": "Legt Basis"}, {"text": "Prototypentwicklung", "correct": true, "because": "Testet Machbarkeit"}, {"text": "Integrationstests", "correct": true, "because": "Sichert Funktion"}, {"text": "Marketingplanung", "correct": false, "because": "Kein Entwurfsschritt"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Anwendungslösungen müssen mit der bestehenden Architektur kompatibel sein. b) Sie dürfen die Architektur nicht verändern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kompatibilität ja, Veränderung möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die bestehende Systemarchitektur setzt technische Grenzen. b) Neue Technologien sind immer erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Grenzen ja, neue Technologien nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Modularität erleichtert die Integration in bestehende Architekturen. b) Entwerfen ohne Architekturkenntnis ist effizient.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Modularität ja, Kenntnislosigkeit nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Anwendungslösungen können die Performance verschlechtern. b) Die bestehende Architektur ist irrelevant für den Entwurf.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Performance ja, Architektur relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Prototypen testen die Realisierbarkeit in bestehenden Architekturen. b) Sicherheit ist beim Entwerfen unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prototypen ja, Sicherheit essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

